-- WHATS'ON usage check for BrOKR — READ-ONLY. Generated from metrics.py; do not edit by hand.
-- Returns counts and metric values only: no user names, no business data.
-- Run each statement in DBeaver (Alt+X runs all) or sqlplus. A failure in one statement
-- (missing table or grant) is itself a finding — note it and continue.

-- PROFILE 1 · Is usage logged, and how far back?
SELECT 'T3TMETRIC' AS tabel, COUNT(*) AS rijen, MIN(T3M_TIMESTAMP) AS oudste, MAX(T3M_TIMESTAMP) AS nieuwste FROM PSI.T3TMETRIC
UNION ALL SELECT 'T3TTABLEMETRIC', COUNT(*), NULL, NULL FROM PSI.T3TTABLEMETRIC
UNION ALL SELECT 'PSIUSER', COUNT(*), MIN(USR_LASTLOGONTIME), MAX(USR_LASTLOGONTIME) FROM PSI.PSIUSER
UNION ALL SELECT 'PSIPRDSTATLOG', COUNT(*), MIN(PRSTAT_DATECHANGED), MAX(PRSTAT_DATECHANGED) FROM PSI.PSIPRDSTATLOG
UNION ALL SELECT 'CM2CONTRACTSTATUSLOG', COUNT(*), MIN(CAST(CSL_DATE AS TIMESTAMP)), MAX(CAST(CSL_DATE AS TIMESTAMP)) FROM PSI.CM2CONTRACTSTATUSLOG
UNION ALL SELECT 'WONDAYSTATUSLOGENTRY', COUNT(*), MIN(DSL_TIMESTAMP), MAX(DSL_TIMESTAMP) FROM PSI.WONDAYSTATUSLOGENTRY
UNION ALL SELECT 'MGXINSTALLATIONHISTORY', COUNT(*), MIN(IH_INSTALLATIONTIMESTAMP), MAX(IH_INSTALLATIONTIMESTAMP) FROM PSI.MGXINSTALLATIONHISTORY
UNION ALL SELECT 'AMUSERACTION', COUNT(*), NULL, NULL FROM PSI.AMUSERACTION
UNION ALL SELECT 'MGXPERFORMANCETRACELOG', COUNT(*), NULL, NULL FROM PSI.MGXPERFORMANCETRACELOG;

-- PROFILE 2 · People vs services (counts only)
SELECT T3M_ISSERVICE AS is_service, COUNT(*) AS transacties, COUNT(DISTINCT T3M_USERNAME) AS gebruikers
FROM PSI.T3TMETRIC WHERE T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30 GROUP BY T3M_ISSERVICE;

-- PROFILE 3 · Application ids (last 30 days)
SELECT T3M_APPLICATIONID AS application_id, COUNT(*) AS transacties FROM PSI.T3TMETRIC
WHERE T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30 GROUP BY T3M_APPLICATIONID ORDER BY 2 DESC FETCH FIRST 25 ROWS ONLY;

-- PROFILE 4 · Tables touched (last 7 days) — checks the module map
SELECT tm.T3MT_TABLENAME AS tabel, COUNT(*) AS keer FROM PSI.T3TTABLEMETRIC tm JOIN PSI.T3TMETRIC m ON m.OID = tm.T3MT_ID_T3METRIC
WHERE m.T3M_TIMESTAMP >= TRUNC(SYSDATE) - 7 GROUP BY tm.T3MT_TABLENAME ORDER BY 2 DESC FETCH FIRST 40 ROWS ONLY;

-- PROFILE 5 · Duration magnitude (unit check)
SELECT MIN(T3M_DUR_TOTAL) AS min_dur, MEDIAN(T3M_DUR_TOTAL) AS mediaan_dur, MAX(T3M_DUR_TOTAL) AS max_dur
FROM PSI.T3TMETRIC WHERE T3M_TIMESTAMP >= TRUNC(SYSDATE) - 7;

-- METRICS (PSI schema)
SELECT 'usage-active-users-30d' AS meting, value FROM (
SELECT COUNT(DISTINCT T3M_USERNAME) AS value FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30
)
UNION ALL
SELECT 'usage-active-users-7d' AS meting, value FROM (
SELECT COUNT(DISTINCT T3M_USERNAME) AS value FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 7
)
UNION ALL
SELECT 'usage-seat-utilisation' AS meting, value FROM (
SELECT ROUND(100 * (SELECT COUNT(DISTINCT T3M_USERNAME) FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30)
       / NULLIF((SELECT COUNT(*) FROM PSI.PSIUSER WHERE NVL(USR_ISDISABLED, 0) = 0 AND NVL(USR_ISSERVERUSER, 0) = 0), 0), 1) AS value FROM DUAL
)
UNION ALL
SELECT 'usage-dormant-accounts' AS meting, value FROM (
SELECT COUNT(*) AS value FROM PSI.PSIUSER WHERE NVL(USR_ISDISABLED, 0) = 0 AND NVL(USR_ISSERVERUSER, 0) = 0 AND (USR_LASTLOGONTIME IS NULL OR USR_LASTLOGONTIME < TRUNC(SYSDATE) - 60)
)
UNION ALL
SELECT 'usage-stickiness' AS meting, value FROM (
SELECT ROUND(100 * AVG(d.users) / NULLIF((SELECT COUNT(DISTINCT T3M_USERNAME) FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30), 0), 1) AS value
FROM (SELECT T3M_TIMESTAMP_DAY, COUNT(DISTINCT T3M_USERNAME) AS users FROM PSI.T3TMETRIC
      WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30 AND TO_CHAR(T3M_TIMESTAMP_DAY, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') NOT IN ('SAT', 'SUN')
      GROUP BY T3M_TIMESTAMP_DAY) d
)
UNION ALL
SELECT 'usage-active-users-trend' AS meting, value FROM (
SELECT ROUND(100 * (cur.n - prev.n) / NULLIF(prev.n, 0), 1) AS value FROM
 (SELECT COUNT(DISTINCT T3M_USERNAME) AS n FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30) cur,
 (SELECT COUNT(DISTINCT T3M_USERNAME) AS n FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 60 AND T3M_TIMESTAMP < TRUNC(SYSDATE) - 30) prev
)
UNION ALL
SELECT 'usage-tx-per-weekday' AS meting, value FROM (
SELECT ROUND(COUNT(*) / 22, 0) AS value FROM PSI.T3TMETRIC
WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30 AND TO_CHAR(T3M_TIMESTAMP, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') NOT IN ('SAT', 'SUN')
)
UNION ALL
SELECT 'usage-changes-30d' AS meting, value FROM (
SELECT NVL(SUM(T3M_NROFCHANGES), 0) AS value FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30
)
UNION ALL
SELECT 'usage-automation-share' AS meting, value FROM (
SELECT ROUND(100 * SUM(CASE WHEN T3M_ISSERVICE = 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 1) AS value FROM PSI.T3TMETRIC WHERE T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30
)
UNION ALL
SELECT 'usage-modules-in-use' AS meting, value FROM (
SELECT COUNT(*) AS value FROM (
  SELECT CASE
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'FSM%' OR UPPER(tm.T3MT_TABLENAME) LIKE 'CM2AMORTIZ%' OR UPPER(tm.T3MT_TABLENAME) LIKE 'CM2PAYMENT%' THEN 'finance'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'CM%'  THEN 'contracts'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'MM2%' THEN 'media'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'TM%'  THEN 'trailers'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'PG%'  THEN 'epg'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'ARL%' THEN 'asrun'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'PSIPRODUCT%' THEN 'content'
      WHEN UPPER(tm.T3MT_TABLENAME) IN ('PSITRANSMISSION','PSITXBLOCK','PSISCHEDULE') OR UPPER(tm.T3MT_TABLENAME) LIKE 'PL%' THEN 'planning'
      ELSE 'other' END AS module, COUNT(DISTINCT m.OID) AS n
  FROM PSI.T3TMETRIC m JOIN PSI.T3TTABLEMETRIC tm ON tm.T3MT_ID_T3METRIC = m.OID
  WHERE m.T3M_ISSERVICE = 0 AND m.T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30
  GROUP BY CASE
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'FSM%' OR UPPER(tm.T3MT_TABLENAME) LIKE 'CM2AMORTIZ%' OR UPPER(tm.T3MT_TABLENAME) LIKE 'CM2PAYMENT%' THEN 'finance'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'CM%'  THEN 'contracts'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'MM2%' THEN 'media'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'TM%'  THEN 'trailers'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'PG%'  THEN 'epg'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'ARL%' THEN 'asrun'
      WHEN UPPER(tm.T3MT_TABLENAME) LIKE 'PSIPRODUCT%' THEN 'content'
      WHEN UPPER(tm.T3MT_TABLENAME) IN ('PSITRANSMISSION','PSITXBLOCK','PSISCHEDULE') OR UPPER(tm.T3MT_TABLENAME) LIKE 'PL%' THEN 'planning'
      ELSE 'other' END) x WHERE x.n >= 50 AND x.module <> 'other'
)
UNION ALL
SELECT 'usage-contract-users-30d' AS meting, value FROM (
SELECT COUNT(DISTINCT m.T3M_USERNAME) AS value FROM PSI.T3TMETRIC m JOIN PSI.T3TTABLEMETRIC tm ON tm.T3MT_ID_T3METRIC = m.OID
WHERE m.T3M_ISSERVICE = 0 AND m.T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30 AND tm.T3MT_TABLENAME LIKE 'CM%'
  AND tm.T3MT_TABLENAME NOT LIKE 'CM2AMORTIZ%' AND tm.T3MT_TABLENAME NOT LIKE 'CM2PAYMENT%'
)
UNION ALL
SELECT 'usage-product-status-changes' AS meting, value FROM (
SELECT COUNT(*) AS value FROM PSI.PSIPRDSTATLOG WHERE PRSTAT_DATECHANGED >= TRUNC(SYSDATE) - 30
)
UNION ALL
SELECT 'usage-contract-status-changes' AS meting, value FROM (
SELECT COUNT(*) AS value FROM PSI.CM2CONTRACTSTATUSLOG WHERE CSL_DATE >= TRUNC(SYSDATE) - 30
)
UNION ALL
SELECT 'usage-day-status-changes' AS meting, value FROM (
SELECT COUNT(*) AS value FROM PSI.WONDAYSTATUSLOGENTRY WHERE DSL_TIMESTAMP >= TRUNC(SYSDATE) - 30
)
UNION ALL
SELECT 'platform-days-since-upgrade' AS meting, value FROM (
SELECT TRUNC(SYSDATE - MAX(CAST(IH_INSTALLATIONTIMESTAMP AS DATE))) AS value FROM PSI.MGXINSTALLATIONHISTORY
)
UNION ALL
SELECT 'platform-median-save-ms' AS meting, value FROM (
SELECT ROUND(MEDIAN(T3M_DUR_TOTAL), 0) AS value FROM PSI.T3TMETRIC WHERE T3M_ISSERVICE = 0 AND T3M_TIMESTAMP >= TRUNC(SYSDATE) - 30
);

-- METRICS (PSILOGGING schema — needs a separate grant)
SELECT 'platform-crashes-30d' AS meting, value FROM (
SELECT COUNT(*) AS value FROM PSILOGGING.WONCRASHREPORTLOG WHERE WCR_TIMESTAMP >= TRUNC(SYSDATE) - 30
);
